content.content:
1	package world
2	
3	import (
4		"encoding/json"
5		"errors"
6		"os"
7		"path/filepath"
8	)
9	
10	// RecordInfo 描述一次保存产生的记录的元信息。
11	type RecordInfo struct {
12		// ID 是记录在存档目录内的唯一标识。
13		ID RecordID
14		// Parent 是父记录标识；直接建立的槽首条记录为空。
15		Parent RecordID
16		// SlotFirst 表示这是所在槽的首条记录（根记录或分支记录）。
17		SlotFirst bool
18		// Version 是记录中世界规则的版本。
19		Version string
20	}
21	
22	// slotPointer 是槽指针文件的磁盘内容，指向该槽当前最新记录。
23	//
24	// History 按该槽“保存生效的次序”记录全部属于本槽的记录标识，最新在前，
25	// 末尾是槽首条记录（直接建立的根记录或分支首记录）。它只在对应记录文件
26	// 已完整落盘后才随指针原子更新，因此绝不会包含写了一半的残留文件、写完
27	// 但尚未完成保存的孤儿记录，或 CAS 竞争失败的写入。恢复读取据此遍历，
28	// 不依赖文件修改时间，也不信任受损记录文件里读出的父标识或槽首标记。
29	//
30	// 旧版本写出的指针没有 History 字段；读取时会在内存中按校验通过的父链
31	// 回退重建，不要求用户转换数据。
32	type slotPointer struct {
33		Latest  RecordID   `json:"latest"`
34		History []RecordID `json:"history,omitempty"`
35	}
36	
37	// archiveMarker 是存档目录的标记文件。
38	type archiveMarker struct {
39		Format int `json:"format"`
40	}
41	
42	// Archive 是一个本地存档目录句柄。多个进程或多个实例可以同时打开
43	// 同一目录；所有写入通过目录内的 flock 串行化。
44	type Archive struct {
45		dir string
46	}
47	
48	const (
49		markerName  = "archive.json"
50		recordsName = "records"
51		slotsName   = "slots"
52	)
53	
54	// Create 在指定目录建立新的存档。目录会被创建；若该目录已经是一个
55	// 存档则返回错误，以免覆盖已有数据。
56	func Create(dir string) (*Archive, error) {
57		if err := os.MkdirAll(dir, 0o755); err != nil {
58			return nil, err
59		}
60		markerPath := filepath.Join(dir, markerName)
61		f, err := os.OpenFile(markerPath, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
62		if err != nil {
63			if errors.Is(err, os.ErrExist) {
64				return nil, &ConflictError{Reason: "目录已是一个存档: " + dir}
65			}
66			return nil, err
67		}
68		markerData, _ := json.Marshal(archiveMarker{Format: archiveFormatVersion})
69		if _, err := f.Write(markerData); err != nil {
70			f.Close()
71			return nil, err
72		}
73		if err := f.Close(); err != nil {
74			return nil, err
75		}
76		for _, sub := range []string{recordsName, slotsName} {
77			if err := os.MkdirAll(filepath.Join(dir, sub), 0o755); err != nil {
78				return nil, err
79			}
80		}
81		// 预先建立锁文件并同步目录，使之后的打开更稳妥。
82		if lf, err := os.OpenFile(filepath.Join(dir, "lock"),
83			os.O_RDWR|os.O_CREATE, 0o600); err == nil {
84			lf.Close()
85		}
86		if err := syncDir(dir); err != nil {
87			return nil, err
88		}
89		return &Archive{dir: dir}, nil
90	}
91	
92	// Open 打开一个此前由 Create 建立的存档目录。
93	func Open(dir string) (*Archive, error) {
94		path := filepath.Join(dir, markerName)
95		f, err := os.Open(path)
96		if err != nil {
97			if errors.Is(err, os.ErrNotExist) {
98				return nil, &NotFoundError{}
99			}
100			return nil, err
101		}
102		defer f.Close()
103		var m archiveMarker
104		if err := json.NewDecoder(f).Decode(&m); err != nil {
105			return nil, &CorruptError{Reason: "存档标记无法解析"}
106		}
107		if m.Format != archiveFormatVersion {
108			return nil, &CorruptError{Reason: "不支持的存档格式版本"}
109		}
110		for _, sub := range []string{recordsName, slotsName} {
111			if fi, err := os.Stat(filepath.Join(dir, sub)); err != nil || !fi.IsDir() {
112				return nil, &CorruptError{Reason: "存档目录结构不完整: 缺少 " + sub}
113			}
114		}
115		return &Archive{dir: dir}, nil
116	}
117	
118	// Dir 返回存档目录路径。
119	func (a *Archive) Dir() string { return a.dir }
120	
121	func (a *Archive) slotPath(slot string) string {
122		return filepath.Join(a.dir, slotsName, slot+".json")
123	}
124	
125	// validSlotName 拒绝空名以及可能逃逸 slots 目录的名字。
126	func validSlotName(slot string) bool {
127		if slot == "" || slot == "." || slot == ".." {
128			return false
129		}
130		if filepath.IsAbs(slot) {
131			return false
132		}
133		for _, r := range slot {
134			if r == '/' || r == '\\' || r == 0 {
135				return false
136			}
137		}
138		return filepath.Clean(slot) == slot
139	}
140	
141	// readSlotPointerLocked 在调用方已持锁的前提下读取并解析槽指针文件。
142	func (a *Archive) readSlotPointerLocked(slot string) (slotPointer, error) {
143		data, err := os.ReadFile(a.slotPath(slot))
144		if err != nil {
145			if errors.Is(err, os.ErrNotExist) {
146				return slotPointer{}, &NotFoundError{Slot: slot}
147			}
148			return slotPointer{}, err
149		}
150		var p slotPointer
151		if err := json.Unmarshal(data, &p); err != nil {
152			return slotPointer{}, &CorruptError{Slot: slot, Reason: "槽指针无法解析"}
153		}
154		if p.Latest == "" {
155			return slotPointer{}, &CorruptError{Slot: slot, Reason: "槽指针为空"}
156		}
157		return p, nil
158	}
159	
160	// readLatestLocked 在调用方已持锁的前提下读取槽当前最新记录标识。
161	func (a *Archive) readLatestLocked(slot string) (RecordID, error) {
162		p, err := a.readSlotPointerLocked(slot)
163		if err != nil {
164			return "", err
165		}
166		return p.Latest, nil
167	}
168	
169	// Save 在存档中保存一个世界。
170	//
171	// 首次保存会创建同名存档槽；槽名已存在时返回 *ConflictError。
172	// 成功后返回新记录的标识，记录包含完整世界数据，且没有父记录。
173	func (a *Archive) Save(slot string, w *World) (RecordInfo, error) {
174		if !validSlotName(slot) {
175			return RecordInfo{}, &ConflictError{Slot: slot, Reason: "非法存档槽名"}
176		}
177		st := w.Snapshot()
178	
179		lock, err := acquireLock(a.dir)
180		if err != nil {
181			return RecordInfo{}, err
182		}
183		defer lock.release()
184	
185		// 持锁后再次确认槽不存在。
186		if _, err := a.readLatestLocked(slot); err == nil {
187			return RecordInfo{}, &ConflictError{Slot: slot, Reason: "存档槽名已存在"}
188		} else if !errors.As(err, new(*NotFoundError)) {
189			return RecordInfo{}, err
190		}
191	
192		id, err := newRecordID()
193		if err != nil {
194			return RecordInfo{}, err
195		}
196		env := &envelope{
197			Format:    archiveFormatVersion,
198			ID:        id,
199			SlotFirst: true,
200			State:     st,
201		}
202		env.Checksum = computeChecksum(env)
203		if err := writeRecord(a.dir, env); err != nil {
204			return RecordInfo{}, err
205		}
206		if err := a.createSlotPointer(slot, id); err != nil {
207			return RecordInfo{}, err
208		}
209		return RecordInfo{ID: id, SlotFirst: true, Version: st.Rules.Version}, nil
210	}
211	
212	// createSlotPointer 以“临时文件写全 + os.Link 原子建立”的方式创建槽
213	// 指针：Link 在目标已存在时失败，因此重名会被明确拒绝，同时崩溃后
214	// 要么没有该槽，要么指向一份完整记录，绝不会留下半写的指针。新槽的
215	// 历史索引只含其首条记录本身——分支槽不会把来源槽的记录计入候选。
216	func (a *Archive) createSlotPointer(slot string, id RecordID) error {
217		slotsDir := filepath.Join(a.dir, slotsName)
218		final := a.slotPath(slot)
219		data, _ := json.MarshalIndent(slotPointer{
220			Latest:  id,
221			History: []RecordID{id},
222		}, "", "  ")
223	
224		tmp := filepath.Join(slotsDir, ".new-"+slot+"-"+randomSuffix()+".tmp")
225		f, err := os.OpenFile(tmp, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
226		if err != nil {
227			return err
228		}
229		if _, err := f.Write(data); err != nil {
230			f.Close()
231			os.Remove(tmp)
232			return err
233		}
234		if err := f.Sync(); err != nil {
235			f.Close()
236			os.Remove(tmp)
237			return err
238		}
239		if err := f.Close(); err != nil {
240			os.Remove(tmp)
241			return err
242		}
243		if err := os.Link(tmp, final); err != nil {
244			os.Remove(tmp)
245			if errors.Is(err, os.ErrExist) {
246				return &ConflictError{Slot: slot, Reason: "存档槽名已存在"}
247			}
248			return err
249		}
250		os.Remove(tmp)
251		return syncDir(slotsDir)
252	}
253	
254	// Replace 用世界当前状态覆盖槽的最新记录。
255	//
256	// expected 必须是调用方此前读到的记录标识，并且它仍是该槽最新记录，
257	// 写入才会发生；否则返回 *ConflictError——即使该标识对应的旧文件恰好
258	// 已损坏或被删除，过期请求也只报冲突，不改报文件错误。标识匹配时还要
259	// 确认这条当前记录本身可正常读取：文件缺失返回 *NotFoundError；截断、
260	// 校验和不匹配、世界状态不合法或父记录缺失返回 *CorruptError。绝不用
261	// 调用方传入的完整世界掩盖当前记录的问题，也不自动改选较老记录为父。
262	// 新记录的父记录就是被覆盖的那次记录。同一目录下并发覆盖同一父记录时
263	// 只有一个成功。被拒绝的覆盖不改变槽指向、历史与任何已有记录。
264	func (a *Archive) Replace(slot string, w *World, expected RecordID) (RecordInfo, error) {
265		if !validSlotName(slot) {
266			return RecordInfo{}, &ConflictError{Slot: slot, Reason: "非法存档槽名"}
267		}
268		if expected == "" {
269			return RecordInfo{}, &ConflictError{Slot: slot, Reason: "覆盖必须提供所依据的记录标识"}
270		}
271		st := w.Snapshot()
272	
273		lock, err := acquireLock(a.dir)
274		if err != nil {
275			return RecordInfo{}, err
276		}
277		defer lock.release()
278	
279		pointer, err := a.readSlotPointerLocked(slot)
280		if err != nil {
281			return RecordInfo{}, err
282		}
283		if pointer.Latest != expected {
284			return RecordInfo{}, &ConflictError{
285				Slot:   slot,
286				Reason: "所依据的记录已不是该槽最新记录",
287			}
288		}
289	
290		// 标识匹配后，当前记录本身必须可正常读取：完整、内容校验通过、
291		// 世界状态合法且父记录关系成立。否则以它为父保存的新记录随后也
292		// 无法读取，等于用调用方传入的完整世界掩盖了当前记录的问题；
293		// 这里沿用与读取路径一致的校验，损坏或缺失时拒绝覆盖，槽指向、
294		// 历史与已有记录保持原样，调用方可改走恢复预览与确认恢复。
295		if _, err := a.loadAndVerifyLocked(expected); err != nil {
296			if ce, ok := err.(*CorruptError); ok {
297				ce.Slot = slot
298			}
299			return RecordInfo{}, err
300		}
301	
302		// 覆盖保存传入世界的快照，以被覆盖的当前记录为父，沿用共同的
303		// 新记录组装、落盘与槽指针提交路径。
304		return a.appendSlotRecordLocked(slotSave{
305			slot:          slot,
306			oldPointer:    pointer,
307			parent:        expected,
308			historyAnchor: expected,
309			state:         st,
310		})
311	}
312	
313	// commitSlotPointerLocked 在记录文件已完整落盘后，原子更新槽指针：指向
314	// 新记录，并把历史索引按保存次序前置新记录。历史索引只在此刻（记录已
315	// 完整生效）才更新，因此残留临时文件与写完但未完成保存的孤儿记录绝不会
316	// 进入恢复候选。
317	func (a *Archive) commitSlotPointerLocked(slot string, oldPointer slotPointer, oldLatest, newID RecordID) error {
318		history, err := a.nextSlotHistoryLocked(oldPointer, oldLatest, newID)
319		if err != nil {
320			return err
321		}
322		return a.persistSlotPointerLocked(slot, slotPointer{Latest: newID, History: history})
323	}
324	
325	// replaceSlotPointer 直接把槽指针指向 id，不附带历史索引。它仅用于测试
326	// 中模拟旧版本或外部写入器留下的指针；生产写入路径一律走
327	// commitSlotPointerLocked 以维护历史索引。
328	func (a *Archive) replaceSlotPointer(slot string, id RecordID) error {
329		return a.persistSlotPointerLocked(slot, slotPointer{Latest: id})
330	}
331	
332	// Branch 从 srcSlot 的指定历史记录 src 分出新槽 dstSlot。
333	//
334	// 新槽的首条记录以 src 为父记录，完整复制当时的种子、规则和状态。
335	// 目标槽名已存在时返回 *ConflictError。源记录必须校验通过。
336	func (a *Archive) Branch(srcSlot string, src RecordID, dstSlot string) (RecordInfo, error) {
337		if !validSlotName(srcSlot) {
338			return RecordInfo{}, &ConflictError{Slot: srcSlot, Reason: "非法源存档槽名"}
339		}
340		if !validSlotName(dstSlot) {
341			return RecordInfo{}, &ConflictError{Slot: dstSlot, Reason: "非法目标存档槽名"}
342		}
343		if src == "" {
344			return RecordInfo{}, &NotFoundError{Slot: srcSlot}
345		}
346	
347		lock, err := acquireLock(a.dir)
348		if err != nil {
349			return RecordInfo{}, err
350		}
351		defer lock.release()
352	
353		srcEnv, err := a.loadAndVerifyLocked(src)
354		if err != nil {
355			return RecordInfo{}, err
356		}
357		// 确认源记录确实属于源槽的历史链，避免拿别的槽的记录冒充分支源。
358		if err := a.assertInSlotHistoryLocked(srcSlot, src); err != nil {
359			return RecordInfo{}, err
360		}
361		// 目标槽重名拒绝创建。
362		if _, err := a.readLatestLocked(dstSlot); err == nil {
363			return RecordInfo{}, &ConflictError{Slot: dstSlot, Reason: "目标存档槽名已存在"}
364		} else if !errors.As(err, new(*NotFoundError)) {
365			return RecordInfo{}, err
366		}
367	
368		id, err := newRecordID()
369		if err != nil {
370			return RecordInfo{}, err
371		}
372		env := &envelope{
373			Format:    archiveFormatVersion,
374			ID:        id,
375			Parent:    src,
376			SlotFirst: true,
377			// 完整复制当时的世界数据；此后两槽各自保存互不影响。
378			State: cloneState(srcEnv.State),
379		}
380		env.Checksum = computeChecksum(env)
381		if err := writeRecord(a.dir, env); err != nil {
382			return RecordInfo{}, err
383		}
384		if err := a.createSlotPointer(dstSlot, id); err != nil {
385			return RecordInfo{}, err
386		}
387		return RecordInfo{
388			ID:        id,
389			Parent:    src,
390			SlotFirst: true,
391			Version:   env.State.Rules.Version,
392		}, nil
393	}
394	
395	// assertInSlotHistoryLocked 确认 id 位于 slot 自身的历史次序中（分支槽
396	// 的历史只含它自己保存成功的记录，不含来源槽记录）。
397	func (a *Archive) assertInSlotHistoryLocked(slot string, id RecordID) error {
398		history, err := a.slotHistoryLocked(slot)
399		if err != nil {
400			return err
401		}
402		for _, cid := range history {
403			if cid == id {
404				return nil
405			}
406		}
407		return &NotFoundError{Slot: slot, Record: id}
408	}
409	
410	// slotHistoryLocked 返回该槽按保存生效次序排列的记录标识（最新在前、
411	// 槽首记录在末尾）。
412	//
413	// 优先使用指针内嵌的历史索引；旧版本指针没有该索引时，在内存中沿
414	// “校验通过”的记录父链回退重建，绝不在读取路径上改写目录。重建在缺失、
415	// 无法解析或校验不过的记录处停止——无法确认归属的更老记录不再使用。
416	// 槽首标记只取自校验通过的信封，因此受损记录里被篡改的父标识或槽首
417	// 标记既不能把遍历引向别的槽，也不能遮住本槽更早的可用记录。
418	func (a *Archive) slotHistoryLocked(slot string) ([]RecordID, error) {
419		p, err := a.readSlotPointerLocked(slot)
420		if err != nil {
421			return nil, err
422		}
423		if len(p.History) > 0 {
424			// 以 Latest 为链头做一次去重规范化，容忍索引中的重复项。
425			return dedupeRecordIDs(append([]RecordID{p.Latest}, p.History...)), nil
426		}
427		return a.rebuildHistoryLocked(p.Latest)
428	}
429	
430	// rebuildHistoryLocked 从 latest 起沿校验通过的父链在内存中重建历史，
431	// 只返回仍能确认属于本槽的记录；在缺失、无法解析或校验不过的记录处停止。
432	func (a *Archive) rebuildHistoryLocked(latest RecordID) ([]RecordID, error) {
433		var chain []RecordID
434		seen := map[RecordID]bool{}
435		cur := latest
436		for cur != "" {
437			if seen[cur] {
438				return nil, &CorruptError{Record: cur, Reason: "历史链出现环"}
439			}
440			seen[cur] = true
441			env, err := a.loadAndVerifyLocked(cur)
442			if err != nil {
443				// 缺失、无法解析或校验不过：无法继续确认更老记录的归属，
444				// 旧历史在此断裂；已确认的部分仍可使用。
445				return chain, nil
446			}
447			chain = append(chain, cur)
448			if env.SlotFirst {
449				return chain, nil
450			}
451			cur = env.Parent
452		}
453		return chain, nil
454	}
455	
456	// dedupeRecordIDs 按首次出现次序去重记录标识。
457	func dedupeRecordIDs(ids []RecordID) []RecordID {
458		seen := map[RecordID]bool{}
459		out := ids[:0]
460		for _, id := range ids {
461			if id == "" || seen[id] {
462				continue
463			}
464			seen[id] = true
465			out = append(out, id)
466		}
467		return out
468	}
469	
470	// persistSlotPointerLocked 以原子改名写出槽指针。
471	func (a *Archive) persistSlotPointerLocked(slot string, p slotPointer) error {
472		data, _ := json.MarshalIndent(p, "", "  ")
473		return writeAtomic(filepath.Join(a.dir, slotsName), slot+".json", data)
474	}
475	
476	// nextSlotHistory 在一次以 oldLatest 为被覆盖/升级记录的成功写入后，
477	// 生成新指针应持有的历史次序：新记录在最前，其余沿用此前已确认属于
478	// 本槽的记录。旧指针无索引时在内存中回退重建（不完整也照样承接），
479	// 从而让旧历史在第一次成功覆盖或升级后获得完整恢复能力。
480	func (a *Archive) nextSlotHistoryLocked(oldPointer slotPointer, oldLatest, newID RecordID) ([]RecordID, error) {
481		base := oldPointer.History
482		if len(base) == 0 {
483			rebuilt, err := a.rebuildHistoryLocked(oldLatest)
484			if err != nil {
485				return nil, err
486			}
487			base = rebuilt
488		}
489		return dedupeRecordIDs(append([]RecordID{newID}, base...)), nil
490	}
491	
492	// Slots 返回所有存档槽名。
493	func (a *Archive) Slots() ([]string, error) {
494		entries, err := os.ReadDir(filepath.Join(a.dir, slotsName))
495		if err != nil {
496			return nil, err
497		}
498		var names []string
499		for _, e := range entries {
500			if e.IsDir() {
501				continue
502			}
503			name := e.Name()
504			if len(name) > 5 && name[len(name)-5:] == ".json" {
505				names = append(names, name[:len(name)-5])
506			}
