1	package world
2	
3	import (
4		"errors"
5		"fmt"
6	)
7	
8	// ConflictError 表示保存与存档当前状态冲突：槽重名、覆盖所依据的
9	// 记录已不是该槽最新记录等。调用方应当重新读取后再决定是否重试。
10	type ConflictError struct {
11		Slot   string
12		Reason string
13	}
14	
15	func (e *ConflictError) Error() string {
16		if e.Slot == "" {
17			return "world: 存档冲突: " + e.Reason
18		}
19		return fmt.Sprintf("world: 存档槽 %q 冲突: %s", e.Slot, e.Reason)
20	}
21	
22	// NotFoundError 表示指定的槽或记录不存在。
