338	
339		// 版本集合不含任何匹配版本 -> 明确拒绝，且不改写。
340		if _, err := a.Latest("s", []string{"v9"}); err == nil {
341			t.Fatal("版本不被接受应返回错误")
342		} else {
343			var vre *VersionRejectedError
344			if !errors.As(err, &vre) {
345				t.Fatalf("应返回 VersionRejectedError，得到 %T", err)
346			}
347		}
348	
349		// 直接写一条 v2 的最新记录（读取侧永远不能替换记录中的规则，
350		// 这里模拟由其他兼容版本写入器产生的数据）。
351		v2State := w.Snapshot()
352		v2State.Time = 2
353		v2State.Rules.Version = "v2"
354		r2 := writeRawRecord(t, a, r1.ID, false, v2State)
355		updatePointer(t, a, "s", r2)
356	
357		// Latest 在仅接受 v1 时拒绝最新记录；恢复读取应越过 v2 找到 r1。
358		if _, err := a.Latest("s", []string{"v1"}); err == nil {
359			t.Fatal("v2 最新记录应被版本拒绝")
360		}
361		rec, err := a.RecoverLatest("s", []string{"v1"})
362		if err != nil {
363			t.Fatalf("应恢复到 v1 历史记录: %v", err)
364		}
365		if rec.ID != r1.ID {
366			t.Fatalf("应恢复到最近可接受记录 %s，得到 %s", r1.ID, rec.ID)
367		}
368		// 恢复读取不改写槽指针与历史。
369		ptr, err := a.readLatestLocked("s")
370		if err != nil {
371			t.Fatal(err)
372		}
373		if ptr != r2 {
374			t.Fatal("恢复读取改写了槽指针")
375		}
376	
377		// 损坏最新记录：改写其校验和（JSON 仍可解析，父指针仍在）。
378		// Latest 报损坏；恢复应越过它，沿父指针找到可接受记录。
379		{
380			path := recordPath(dir, r2)
381			raw, err := os.ReadFile(path)
382			if err != nil {
383				t.Fatal(err)
384			}
385			s := string(raw)
386			i := strings.Index(s, `"checksum": "`)
387			if i < 0 {
388				t.Fatal("找不到 checksum 字段")
389			}
390			start := i + len(`"checksum": "`)
391			end := start + 64
392			s = s[:start] + strings.Repeat("0", 64) + s[end:]
393			if err := os.WriteFile(path, []byte(s), 0o600); err != nil {
394				t.Fatal(err)
395			}
396		}
397		if _, err := a.Latest("s", []string{"v1", "v2"}); err == nil {
398			t.Fatal("损坏记录应报错")
399		} else {
400			var ce *CorruptError
401			if !errors.As(err, &ce) {
402				t.Fatalf("应返回 CorruptError，得到 %T", err)
403			}
404		}
405		rec2, err := a.RecoverLatest("s", []string{"v1"})
406		if err != nil {
407			t.Fatalf("应越过损坏记录恢复: %v", err)
408		}
409		if rec2.ID != r1.ID {
410			t.Fatalf("恢复结果错误: %s", rec2.ID)
411		}
412	
413		// 连最后可接受的根也不可接受时 -> 不可恢复。
414		_, err = a.RecoverLatest("s", []string{"v9"})
415		if !errors.Is(err, ErrUnrecoverable) {
416			t.Fatalf("应返回 ErrUnrecoverable，得到 %T: %v", err, err)
417		}
418	
419		// r0 仍完好且可按标识读取（在进一步截断链之前）。
420		r0rec, err := a.Record("s", r0.ID, []string{"v1"})
421		if err != nil {
422			t.Fatal(err)
423		}
424		if r0rec.ID != r0.ID {
425			t.Fatal("根记录读取错误")
426		}
427	
428		// 最新记录被截断到无法解析时，历史索引仍保留保存次序，恢复应越过
429		// 它找到更早的可用记录（不能因为读不出父标识就放弃）。
430		if err := os.Truncate(recordPath(dir, r2), 40); err != nil {
431			t.Fatal(err)
432		}
433		rec3, err := a.RecoverLatest("s", []string{"v1"})
434		if err != nil {
435			t.Fatalf("最新记录被截断成无法解析的内容时仍应恢复到更早记录: %v", err)
436		}
437		if rec3.ID != r1.ID {
438			t.Fatalf("应越过被截断的最新记录恢复到 %s，得到 %s", r1.ID, rec3.ID)
439		}
440		// 重新打开存档后结果一致。
441		a3, err := Open(dir)
442		if err != nil {
443			t.Fatal(err)
444		}
445		rec4, err := a3.RecoverLatest("s", []string{"v1"})
446		if err != nil {
447			t.Fatalf("重开后恢复结果不一致: %v", err)
448		}
449		if rec4.ID != r1.ID {
450			t.Fatalf("重开后应恢复到 %s，得到 %s", r1.ID, rec4.ID)
451		}
452	}
