603	// updatePointer 模拟一个遵循磁盘格式的写入器：新记录已完整落盘后原子
604	// 更新槽指针，并把新记录按保存次序前置到历史索引。
605	func updatePointer(t *testing.T, a *Archive, slot string, id RecordID) {
606		t.Helper()
607		lock, err := acquireLock(a.dir)
608		if err != nil {
609			t.Fatal(err)
610		}
611		defer lock.release()
612		old, err := a.readSlotPointerLocked(slot)
613		if err != nil {
614			t.Fatal(err)
615		}
616		history := []RecordID{id}
617		for _, hid := range old.History {
618			if hid != id {
619				history = append(history, hid)
620			}
621		}
622		if err := a.persistSlotPointerLocked(slot, slotPointer{Latest: id, History: history}); err != nil {
623			t.Fatal(err)
624		}
625	}
