	}
	// 用户原有文件，必须保留。
	keep := filepath.Join(target, "keep.txt")
	if err := os.WriteFile(keep, []byte("mine"), 0o600); err != nil {
		t.Fatal(err)
	}
	if err := os.Remove(target + "/records"); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(target+"/records", []byte("block"), 0o600); err != nil {
		t.Fatal(err)
	}
	if _, err := Create(target); err == nil {
		t.Fatal("占用时应失败")
	}
	if _, err := os.Stat(filepath.Join(target, markerName)); !errors.Is(err, os.ErrNotExist) {
		t.Fatal("失败后不应留下标记")
	}
	if _, err := os.Stat(filepath.Join(target, "lock")); !errors.Is(err, os.ErrNotExist) {
		t.Fatal("失败后不应留下锁文件")
	}
	if _, err := os.Stat(filepath.Join(target, slotsName)); !errors.Is(err, os.ErrNotExist) {
		t.Fatal("失败后不应留下 slots 目录")
	}
	if b, err := os.ReadFile(keep); err != nil || string(b) != "mine" {
		t.Fatal("用户原有文件应保留")
	}
	if err := os.Remove(target + "/records"); err != nil {
		t.Fatal(err)
	}
	a, err := Create(target)
	if err != nil {
		t.Fatalf("排除占用后应能创建: %v", err)
	}
	w := baseWorld(t)
	if _, err := a.Save("s", w); err != nil {
		t.Fatalf("创建后应能立即保存: %v", err)
	}
	if _, err := Open(target); err != nil {
		t.Fatalf("应能被 Open 打开: %v", err)
	}
	if _, err := a.Latest("s", []string{"v1"}); err != nil {
		t.Fatalf("应能读回: %v", err)
	}

	// 2. lock 位置已是目录 -> 明确失败并回退。
	dir2 := t.TempDir()
	t2 := filepath.Join(dir2, "b")
	if err := os.MkdirAll(filepath.Join(t2, "lock"), 0o755); err != nil {
		t.Fatal(err)
	}
	if _, err := Create(t2); err == nil {
		t.Fatal("lock 为目录时应失败")
	}
	if _, err := os.Stat(filepath.Join(t2, markerName)); !errors.Is(err, os.ErrNotExist) {
		t.Fatal("失败后不应留下标记")
	}
	if fi, err := os.Stat(filepath.Join(t2, "lock")); err != nil || !fi.IsDir() {
		t.Fatal("原有 lock 目录应保留")
	}

	// 3. 已有存档（标记无法解析）-> ConflictError，标记原样保留。
	dir3 := t.TempDir()
	t3 := filepath.Join(dir3, "c")
	if err := os.MkdirAll(t3, 0o755); err != nil {
		t.Fatal(err)
	}
	bad := filepath.Join(t3, markerName)
	if err := os.WriteFile(bad, []byte("{oops"), 0o600); err != nil {
		t.Fatal(err)
	}
	if _, err := Create(t3); err == nil {
		t.Fatal("已有标记应冲突")
	} else {
		var ce *ConflictError
		if !errors.As(err, &ce) {
			t.Fatalf("应返回 ConflictError，得到 %T: %v", err, err)
		}
	}
	if b, _ := os.ReadFile(bad); string(b) != "{oops" {
		t.Fatal("旧标记不应被覆盖或删除")
	}

	// 4. 预先存在的空 records/slots 子目录：成功时沿用；失败时保留。
	dir4 := t.TempDir()
	t4 := filepath.Join(dir4, "d")
	if err := os.MkdirAll(filepath.Join(t4, "records"), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.MkdirAll(filepath.Join(t4, "slots"), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.MkdirAll(filepath.Join(t4, "lock"), 0o755); err != nil { // 强制失败
		t.Fatal(err)
	}
	if _, err := Create(t4); err == nil {
		t.Fatal("应失败")
	}
	for _, sub := range []string{"records", "slots"} {
		if fi, err := os.Stat(filepath.Join(t4, sub)); err != nil || !fi.IsDir() {
			t.Fatalf("原有空子目录 %s 应保留", sub)
		}
	}
	if _, err := os.Stat(filepath.Join(t4, markerName)); !errors.Is(err, os.ErrNotExist) {
		t.Fatal("失败后不应留下标记")
	}
}
